ON CONFLICT (codigo) DO NOTHING;
UPDATE transversal.error_knowledge SET evidencia=evidencia||E'\n28/11: pg_proc proacl producción {postgres=X/postgres} verificado por GPT; local NULL reportado por Claude; diferencia efectiva local pendiente.' WHERE codigo='SALY-F1-WIRE-ACL-PARITY-20261128-001' AND position('pg_proc proacl producción' in evidencia)=0;
UPDATE transversal.error_knowledge SET evidencia=evidencia||E'\n28/11: Claude reporta md5 de las siete funciones reemplazadas idénticos entre base local y producción; sin hashes históricos de filas ni reproducción independiente. No acredita T08 completo.' WHERE codigo='SALY-F1-FIXTURE-COVERAGE-20261128-001' AND position('md5 de las siete funciones' in evidencia)=0;
DO $qa$ BEGIN
IF (SELECT count(*) FROM public.lf_error_knowledge WHERE codigo IN ('SALY-F1-CI-SHADOW-CHECK-20261128-001','SALY-F1-CI-EMPTY-SUCCESS-20261128-001','SALY-F1-TRAIN-PRECHECK-20261128-001','SALY-F1-EKB-RO-ACL-20261128-001','SALY-F1-MATRIX-PROVENANCE-20261128-001','SALY-F1-CI-PATH-FILTER-20261128-001'))<>6 THEN RAISE EXCEPTION 'SALY_F1_CI_EKB_COUNT_INVALID'; END IF;
IF NOT EXISTS (SELECT 1 FROM public.lf_error_knowledge WHERE codigo='SALY-F1-WIRE-ACL-PARITY-20261128-001' AND evidencia LIKE '%pg_proc proacl producción%') OR NOT EXISTS (SELECT 1 FROM public.lf_error_knowledge WHERE codigo='SALY-F1-FIXTURE-COVERAGE-20261128-001' AND evidencia LIKE '%md5 de las siete funciones%') THEN RAISE EXCEPTION 'SALY_F1_EKB_EVIDENCE_MISSING'; END IF;
END $qa$;
COMMIT;
